namespace RecipeHub.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Description = "A simple and delicious pizza with fresh basil and mozzarella.",
            Ingredients = "Pizza dough\nSan Marzano tomatoes\nFresh mozzarella\nFresh basil\nOlive oil\nSalt",
            Steps = "1. Preheat oven to 475°F.\n2. Roll out dough on floured surface.\n3. Spread crushed tomatoes evenly.\n4. Tear mozzarella and distribute over sauce.\n5. Bake for 10-12 minutes until crust is golden.\n6. Top with fresh basil and drizzle with olive oil."
        },
        new Recipe
        {
            Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
            Description = "Creamy Roman pasta made with eggs, cheese, and pancetta.",
            Ingredients = "Spaghetti\nPancetta\nEggs\nPecorino Romano\nBlack pepper",
            Steps = "1. Cook spaghetti in salted water.\n2. Crisp pancetta in a pan.\n3. Whisk eggs with grated pecorino and pepper.\n4. Toss hot pasta with pancetta.\n5. Remove from heat and stir in egg mixture.\n6. Serve immediately with extra cheese."
        },
        new Recipe
        {
            Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
            Description = "Tender chicken pieces in a creamy spiced tomato sauce.",
            Ingredients = "Chicken breast\nYogurt\nGaram masala\nTurmeric\nTomato sauce\nHeavy cream\nOnion\nGarlic\nGinger",
            Steps = "1. Marinate chicken in yogurt and spices for 2 hours.\n2. Grill or bake chicken until charred.\n3. Sauté onion, garlic, and ginger.\n4. Add tomato sauce and spices, simmer 15 minutes.\n5. Stir in cream and add chicken.\n6. Serve over basmati rice."
        },
        new Recipe
        {
            Id = 4, Title = "Vegetable Pad Thai", Category = "Thai",
            Description = "A vibrant stir-fried noodle dish with crunchy vegetables.",
            Ingredients = "Rice noodles\nTofu\nBean sprouts\nCarrots\nGreen onions\nPeanuts\nLime\nFish sauce\nTamarind paste\nSugar",
            Steps = "1. Soak rice noodles in warm water.\n2. Press and cube tofu, pan-fry until golden.\n3. Make sauce: mix tamarind, fish sauce, and sugar.\n4. Stir-fry vegetables until crisp-tender.\n5. Add noodles and sauce, toss together.\n6. Top with peanuts, bean sprouts, and lime wedge."
        },
        new Recipe
        {
            Id = 5, Title = "Beef Tacos", Category = "Mexican",
            Description = "Seasoned ground beef in warm tortillas with fresh toppings.",
            Ingredients = "Ground beef\nTaco seasoning\nCorn tortillas\nLettuce\nTomato\nCheddar cheese\nSour cream\nSalsa",
            Steps = "1. Brown ground beef in a skillet.\n2. Add taco seasoning and water, simmer 5 minutes.\n3. Warm tortillas in a dry pan.\n4. Assemble tacos with beef and toppings.\n5. Serve with salsa and sour cream."
        },
        new Recipe
        {
            Id = 6, Title = "Chocolate Lava Cake", Category = "Desserts",
            Description = "Rich individual chocolate cakes with a molten center.",
            Ingredients = "Dark chocolate\nButter\nEggs\nSugar\nFlour\nVanilla extract",
            Steps = "1. Preheat oven to 425°F.\n2. Melt chocolate and butter together.\n3. Whisk eggs, sugar, and vanilla.\n4. Fold chocolate mixture into eggs.\n5. Add flour and pour into greased ramekins.\n6. Bake 12-14 minutes until edges are set.\n7. Invert onto plates and serve immediately."
        }
    };

    private readonly Dictionary<int, List<int>> _ratings = new();

    public IReadOnlyList<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();
    }

    public IReadOnlyList<Recipe> GetRecipesByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetRecipe(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        if (stars < 1 || stars > 5) return;

        if (!_ratings.ContainsKey(recipeId))
            _ratings[recipeId] = new List<int>();

        _ratings[recipeId].Add(stars);

        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe != null)
        {
            recipe.RatingCount = _ratings[recipeId].Count;
            recipe.AverageRating = _ratings[recipeId].Average();
        }
    }

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(recipe);
    }
}

